    "7686": "Локальный приоритет данных",
    "7687": ", чтобы эффективно защитить конфиденциальность и безопасность пользователей, а его основные технические принципы логически согласуются с распространенным в отрасли механизмом хэширования (Hash).",
    "7688": "Проще говоря",
    "7689": ", система с помощью алгоритма шифрования сгенерирует уникальный характерный идентификатор (длиной 16–128 символов) для каждого файла, который эквивалентен уникальному идентификатору файла.",
    "7690": "Создать этот идентификатор",
    "7691": "Единственная предпосылка",
    "7692": ", пользователь сохраняет файл локально и завершает расчет алгоритма. Приложение не будет раскрывать идентификатор файла третьим лицам. Только с этим идентификатором можно запросить данные анализа соответствующего идентификатора с сервера, и другого способа их получить нет.",
    "7693": "даже в",
    "7694": "При крайних предположениях",
    "7695": "(Сервер был взломан), третьи лица могут получать только данные анализа файлов и соответствующие идентификаторы, а алгоритмы идентификаторов различных платформ полностью независимы и не связаны с идентификаторами файлов таких платформ, как Baidu Netdisk, и не могут сопоставлять исходные файлы на разных платформах.",
    "7696": "в то же время,",
    "7697": "Сервер хранит только аналитические данные",
    "7698": ": включая интеллектуальные имена файлов, теги, сводку содержимого, оценки и причины, метаданные и т. д., которые вы можете увидеть на панели свойств справа. Сам файл никогда не будет загружен или сохранен.",
