    "9794": "Зарегистрируйтесь и получите пробную версию за 10 долларов США. Кредитная карта не требуется. Кредит действителен в течение 3 месяцев. Включает модели Jamba Large и Jamba Mini.",
    "9795": "Израиль",
    "9800": "Alibaba Cloud Bailian (международная версия)",
    "9801": "После регистрации каждая модель Tongyi Qianwen получит 1 миллион бесплатных жетонов, действительных в течение 90 дней (международный/сингапурский регион). Кредитная карта не требуется.",
    "9803": "Бесплатный «пробный» ключ API, кредитная карта не требуется. 1000 вызовов API в месяц. Только для некоммерческого использования.",
    "9804": "Канада",
    "9816": "Бесплатный «Экспериментальный» план, кредитная карта не требуется. Примерно 1 миллиард токенов в месяц. Ключевые слова могут использоваться для улучшения модели.",
    "9825": "Жипу А.И.",
    "9826": "Предлагает навсегда бесплатные модели, кредитная карта не требуется.",
    "9829": "Бесплатно, кредитная карта не требуется. Чрезвычайно быстрое мышление (около 2600 токенов/с). Дневной лимит в 1 миллион токенов. Ограничение контекста бесплатного файла 8K. Поддержка llama3.1-8b будет прекращена 27 мая 2026 г.",
    "9835": "10 000 нейронов бесплатно каждый день. Бесплатная версия предлагает более 50 моделей.",
    "9841": "Бесплатные кредиты на прототипирование для всех пользователей GitHub. Содержит более 45 моделей. Существует ограничение на один запрос (вход 8K/выход 4K).",
    "9846": "Бесплатно, кредитная карта не требуется. Чрезвычайно быстрый вывод LPU.",
    "9851": "Предоставьте бесплатным пользователям ежемесячную квоту службы вывода в 100 000 раз. Маршруты к таким поставщикам, как Fireworks, Together, Hyperbolic, Nebius, Novita, DeepInfra и другим. Поддерживает тысячи моделей.",
    "9855": "Бесплатная модель, кредитная карта не требуется. `kilo-auto/free` автоматически маршрутизируется к minimax/minimax-m2.5:free (80%) и Stepfun/step-3.5-flash:free (20%).",
    "9857": "Бесшовный шлюз API. Для базового доступа регистрация не требуется. Поддерживает более 30 моделей. Соответствует GDPR.",
    "9858": "Великобритания",
    "9862": "МодельОбъем",
    "9863": "Предоставляет бесплатные услуги вывода API зарегистрированным пользователям. Вам необходимо привязать свою учетную запись Alibaba Cloud и пройти аутентификацию по настоящему имени.",
    "9868": "Зарегистрируйтесь и получите бесплатный кредит в размере 1 доллара США. Кредитная карта не требуется. Через API-интерфейс, совместимый с OpenAI, доступно более 60 моделей с открытым исходным кодом. Штаб-квартира находится в ЕС.",
    "9869": "Нидерланды",
    "9872": "Зарегистрируйтесь и получите бесплатный кредит в размере 5 долларов США. Кредитная карта не требуется. Суверенный провайдер ЕС с центром обработки данных, расположенным в Норвегии. Никаких ограничений скорости, никаких холодных запусков.",
    "9874": "Бесплатно с качественными ограничениями на использование. Предлагает более 400 моделей из библиотеки Ollama. Несовместимо с OpenAI SDK. Используйте [Ollama API](https://docs.ollama.com/cloud).",
    "9877": "OVHcloud AI-терминал",
    "9878": "Бесплатный анонимный профиль (без ключа API, регистрация не требуется): ограничение 2 об/мин для каждой модели и IP-адреса. Хостинг более 40 весовых моделей с открытым исходным кодом в ЕС. Совместимость с OpenAI SDK.",
    "9882": "Бесплатная ежедневная квота токенов, кредитная карта не требуется. Предназначен для ролевых игр и создания историй.",
    "9885": "Количество запросов в минуту ограничено до 20. Если запрос будет слишком быстрым за короткий промежуток времени, сработает ограничение частоты (нужно подождать 1 минуту и ​​повторить попытку)",
    "9886": "Сингапур",
    "9889": "Быстрая и эффективная модель Sapiens AI поддерживает понимание изображений.",
    "9892": "Переключение простых категорий",
