    "11110": "На основе атрибутов DSL, таких как интеллектуальные имена файлов, даты изменения, метки размеров и серийные номера с автоматическим приращением, вы можете переименовывать интеллектуальные имена файлов в пакетном режиме одним щелчком мыши.",
