    "11153": "[Новые модели] Qwen3.8, Ornith-1.5 и другие новейшие модели, получившие высокие оценки сообщества, а также некоторые устаревшие модели были удалены.",
    "11154": "[Производительность пользовательского интерфейса] Удалите всю анимацию пользовательского интерфейса, занимающую графический процессор.",
    "11155": "[Стабильная архитектура] Удалены возможные несовместимые оптимизации, представленные в версии 3.4 для различных аппаратных сред.",
