    "11158": "{count} ожидающие группы, найденные в других категориях политик. Нажмите кнопку ниже, чтобы просмотреть их все.",
    "11159": "Просмотреть все результаты: {count}",
    "11161": "[Пакетное переименование] Поддержка пакетного переименования интеллектуальных имен файлов после завершения анализа.",
    "11162": "[Пакетные теги] Поддержка пакетного добавления и удаления тегов к файлам после завершения анализа.",
    "11163": "[Пакетная очистка] Сканирование для удаления дубликатов, выявления ошибок именования и расширения, а также оптимизации и исправления.",
    "11164": "Точный контент, согласованный",
    "11165": "Похожие фотографии",
    "11166": "Конверсия оптимизации видео",
    "11167": "[Наследование правил анализа] Стратегии анализа профилирования каталогов, интеллектуальные правила имен файлов и дополнительные атрибуты поддерживают наследование.",
    "11168": "[Встроенная модель] Переключитесь на высокоскоростную модель LFM2.5-1.2B, выполните анализ за 2 секунды.",
    "11169": "Омни-мультимодальное двухдорожечное сканирование...",
    "11171": "[Генерация структуры каталогов] Поддерживает копирование слов подсказки одним щелчком мыши во внешний AI, такой как Doubao, для получения высококачественной структуры каталогов файлов.",
