    "11369": "Поиск занимает продолжительное время",
    "11370": "Сканирование Exif-метаданных изображений (например, GPS-координат, данных об оборудовании, времени съёмки и другой конфиденциальной информации), после очистки сохраняется копия без конфиденциальных данных в директорию .VirtualDirectory/.cleaned_exif, оригинальные файлы полностью сохраняются.",
