    "19965": "В настоящее время текущий файл не может быть интеллектуально сгруппирован, пожалуйста, подтвердите, что анализ файла с помощью искусственного интеллекта завершен",
    "19966": "Не удалось создать интеллектуальную схему кластеризации, пожалуйста, повторите попытку",
    "19967": "Интеллектуальная кластеризация",
    "19968": "Сохраненный виртуальный каталог: _BOS_}",
    "19969": "Не удалось сохранить виртуальный каталог, пожалуйста, повторите попытку",
    "19970": "Автоматически сгруппированные темы файлов на основе конечных плотных векторов 384d, с нулевым потреблением токенов, могут быть предварительно просмотрены и сохранены в виде виртуального каталога",
    "19971": "Введите запрос руководства по сопоставлению (необязательно, например: классификация по годам и финансам).",
    "19972": "Перегруппироваться",
    "19973": "Анализ семантики файлов и темы кластеризации...",
    "19974": "Схемы кластеризации нет, пожалуйста, повторите попытку или измените направляющее слово",
    "19975": "Имя виртуального каталога",
    "19976": "Например: Мой каталог интеллектуального кластера",
    "19977": "Экономия...",
    "19978": "Сохранить как виртуальный каталог",
    "19979": "Подавление шума и извлечение транскрипции голоса выполняются за N секунд до перехвата аудио- и видеосигнала, максимальное значение составляет 100 секунд, и эта настройка слишком велика, чтобы увеличить время перехвата.",
    "19980": "Расшифровка голоса выполняется за N секунд до перехвата аудио- и видеосигнала, что увеличивает время анализа и даже приводит к сбою при превышении тайм-аута.",
    "19981": "Аудиотекст",
    "19982": "слова песни",
    "19983": "Текста с расшифровкой голоса пока нет",
    "19984": "Данных о текстах песен пока нет",
    "19987": "Автоматически группировать разделы файлов на основе конечных плотных векторов размером 384d для создания схемы сортировки каталогов",
    "19988": "Кластеризация на уровне миллисекунд на конечной стороне, нулевое потребление токенов",
    "19989": "После подтверждения предварительного просмотра сохраните его как виртуальный каталог одним щелчком мыши",
    "19990": "Не изменяет реальную файловую структуру каталога",
